// MUTHUR MQTT -> InfluxDB batch points
//
// Topic shape:  MUTHUR/<class>/<node>/<metric>
//   class   NDATA | DDATA | DIAG | PND      -> tag "class"
//   node    FLOW | CMPST | PLNT | BASE ...  -> the Influx measurement
//   metric  RATE_LPM | TEMP_C | STATUS ...  -> the Influx field name
//
// Scalar payloads ("7.50") become one field named after the metric.
// JSON payloads (the STATUS topics) become one field per key.

const NO_READING = ['--', 'nan', 'NaN', 'null', 'undefined'];

const parts = String(msg.topic || '').split('/');
if (parts.length !== 4 || parts[0] !== 'MUTHUR') {
    node.warn('Ignoring unrecognised topic: ' + msg.topic);
    return null;
}
const group = parts[0], cls = parts[1], nodeId = parts[2], metric = parts[3];

// The MQTT node may hand us a Buffer or a string depending on its output
// setting; normalise either way.
const raw = (msg.payload === null || msg.payload === undefined)
    ? '' : String(msg.payload).trim();

// An empty payload is a retained-message clear, not a reading.
if (raw === '' || NO_READING.indexOf(raw) !== -1) { return null; }

const fields = {};
const tags = { group: group, class: cls, node: nodeId };

function addValue(key, value) {
    key = String(key).toLowerCase();

    if (typeof value === 'boolean') { fields[key] = value; return; }

    if (typeof value === 'number') {
        // NaN and Infinity are not writable; dropping beats inventing.
        if (isFinite(value)) { fields[key] = value; }
        return;
    }

    if (typeof value !== 'string') { return; }

    const t = value.trim();
    if (t === '' || NO_READING.indexOf(t) !== -1) { return; }
    if (t === 'true' || t === 'false') { fields[key] = (t === 'true'); return; }

    // Number() accepts '' and whitespace as 0, which is why the empty
    // check above comes first.
    const n = Number(t);
    if (isFinite(n)) { fields[key] = n; return; }

    // Descriptive text, e.g. device: "Arduino UNO R4 WiFi". Tags are
    // indexed and queryable - keep what lands here low-cardinality.
    tags[key] = t;
}

function walk(obj, prefix) {
    Object.keys(obj).forEach(function (k) {
        const v = obj[k];
        const key = prefix ? prefix + '_' + k : k;
        if (v && typeof v === 'object' && !Array.isArray(v)) { walk(v, key); }
        else { addValue(key, v); }
    });
}

let parsed = null;
if (raw.charAt(0) === '{') {
    try {
        parsed = JSON.parse(raw);
    } catch (e) {
        node.warn('Bad JSON on ' + msg.topic + ': ' + e.message);
        return null;
    }
}

if (parsed && typeof parsed === 'object') {
    walk(parsed, '');
} else {
    addValue(metric, raw);
}

// Nothing usable survived - e.g. a STATUS document whose values were all
// sentinels. Writing an empty point would be rejected by Influx.
if (Object.keys(fields).length === 0) { return null; }

// Devices here have no RTC, so the only honest timestamp is ingest time.
msg.payload = [{
    measurement: nodeId,
    fields: fields,
    tags: tags,
    timestamp: new Date()
}];
return msg;
